def icon(name: str, cls: str = "") -> str:
    vb, d = ICONS[name]
    c = f"ico {cls}".strip()
    return (f'<svg class="{c}" viewBox="{vb}" aria-hidden="true" focusable="false">'
            f'<path fill="currentColor" d="{d}"/></svg>')
